// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

contract FeatureRegistry {
    mapping(bytes32 => bool) public features;
    address public admin;

    constructor() {
        admin = msg.sender;
    }

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    function setFeature(bytes32 featureId, bool enabled) external onlyAdmin {
        features[featureId] = enabled;
    }

    function isEnabled(bytes32 featureId) external view returns (bool) {
        return features[featureId];
    }
}

contract NetworkProxy is Ownable {
    FeatureRegistry public registry;

    mapping(address => bool) public allowedTargets;
    mapping(address => uint256) public nonces;
    mapping(bytes32 => address) public routeImplementations;

    bytes32 public constant FEATURE_DELEGATECALL = keccak256("FEATURE_DELEGATECALL");
    bytes32 public constant FEATURE_BATCH = keccak256("FEATURE_BATCH");
    bytes32 public constant FEATURE_GASLESS = keccak256("FEATURE_GASLESS");

    event RouteRegistered(bytes32 indexed routeId, address implementation);
    event Executed(address indexed target, bool success, bytes returnData);
    event BatchExecuted(uint256 count);

    constructor(address _registry) Ownable(msg.sender) {
        registry = FeatureRegistry(_registry);
    }

    function registerRoute(bytes32 routeId, address implementation) external onlyOwner {
        require(implementation != address(0), "Zero address");
        require(implementation.code.length > 0, "Not a contract");
        routeImplementations[routeId] = implementation;
        allowedTargets[implementation] = true;
        emit RouteRegistered(routeId, implementation);
    }

    function removeRoute(bytes32 routeId) external onlyOwner {
        address impl = routeImplementations[routeId];
        allowedTargets[impl] = false;
        delete routeImplementations[routeId];
    }

    function _validateTarget(address target) internal view returns (bool) {
        return allowedTargets[target] && target.code.length > 0;
    }

    function _executeCall(address target, bytes memory data) internal returns (bool, bytes memory) {
        require(_validateTarget(target), "Invalid target");
        (bool success, bytes memory returnData) = target.call(data);
        emit Executed(target, success, returnData);
        return (success, returnData);
    }

    function execute(bytes32 routeId, bytes calldata data) external returns (bytes memory) {
        address target = routeImplementations[routeId];
        require(target != address(0), "Route not found");

        (bool success, bytes memory returnData) = _executeCall(target, data);
        require(success, "Call failed");
        return returnData;
    }

    function batchExecute(
        bytes32[] calldata routeIds,
        bytes[] calldata dataArray
    ) external returns (bytes[] memory results) {
        require(registry.isEnabled(FEATURE_BATCH), "Batch not enabled");
        require(routeIds.length == dataArray.length, "Length mismatch");
        require(routeIds.length <= 10, "Too many calls");

        results = new bytes[](routeIds.length);

        for (uint256 i = 0; i < routeIds.length; i++) {
            results[i] = execute(routeIds[i], dataArray[i]);
        }

        emit BatchExecuted(routeIds.length);
        return results;
    }

    function gaslessExecute(
        bytes32 routeId,
        bytes calldata data,
        address sender,
        uint256 nonce,
        bytes calldata signature
    ) external returns (bytes memory) {
        require(registry.isEnabled(FEATURE_GASLESS), "Gasless not enabled");
        require(nonces[sender] == nonce, "Invalid nonce");

        bytes32 messageHash = keccak256(abi.encodePacked(routeId, data, sender, nonce, block.chainid, address(this)));
        bytes32 ethSignedHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash));

        address recovered = _recoverSigner(ethSignedHash, signature);
        require(recovered == sender, "Invalid signature");

        nonces[sender]++;

        address target = routeImplementations[routeId];
        require(target != address(0), "Route not found");

        (bool success, bytes memory returnData) = _executeCall(target, data);
        require(success, "Call failed");
        return returnData;
    }

    function _recoverSigner(bytes32 hash, bytes calldata sig) internal pure returns (address) {
        require(sig.length == 65, "Invalid sig length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(sig.offset)
            s := calldataload(add(sig.offset, 32))
            v := byte(0, calldataload(add(sig.offset, 64)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "Invalid v");
        // Enforce canonical (low-s) signatures to prevent signature malleability (EIP-2)
        require(
            uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0,
            "Invalid s value"
        );
        address signer = ecrecover(hash, v, r, s);
        require(signer != address(0), "Invalid signer");
        return signer;
    }

    receive() external payable {}
}
